<script setup>
import {computed,inject,ref,watch} from 'vue';
import {agentReportKey} from '../../../lib/cc-agent-report-context';
import {marketingReport} from '../../../lib/cc-marketing-report';
import {reportGroups} from '../../../lib/cc-visit-report';
import {branchOf,downloadCsv,maskPhone,visitStatus} from '../../../lib/cc';
import CCDataTable from '../CCDataTable.vue';
import CCPager from '../CCPager.vue';
import CCChipPicker from '../CCChipPicker.vue';
import CCReportKpiRanking from './CCReportKpiRanking.vue';
import CCAgentScorecard from './CCAgentScorecard.vue';
import CCAgentPeriodComparison from './CCAgentPeriodComparison.vue';
import CCReportTrendChart from './CCReportTrendChart.vue';
const {agentScope,financial,financialLoading,financialError,loadFinancial,applied,rows,openLead,printReport}=inject(agentReportKey);
const scopeMode=computed({get:()=>agentScope.value.mode,set:value=>agentScope.value.mode=value}),selectedAgents=computed({get:()=>agentScope.value.multiple,set:value=>agentScope.value.multiple=value}),selected=computed({get:()=>agentScope.value.single,set:value=>agentScope.value.single=value});
const matrix=ref(false),mix=ref('source'),invoicePage=ref(1);
const query=ref(''),outcome=ref(''),page=ref(1),invoiceQuery=ref(''),detail=ref(null),detailTitle=ref('');
const all=computed(()=>financial.value?.rows||rows.value);
const owners=computed(()=>[...new Set(all.value.map(r=>r.lead_owner).filter(Boolean))].sort());
const inScope=r=>scopeMode.value==='all'||(scopeMode.value==='single'?r.lead_owner===selected.value:selectedAgents.value.includes(r.lead_owner));
const scoped=computed(()=>({...financial.value,rows:all.value.filter(inScope),cc_invoice_report_summary:{...financial.value?.cc_invoice_report_summary,payment_rows:(financial.value?.cc_invoice_report_summary?.payment_rows||[]).filter(inScope)}}));
const funnel=computed(()=>marketingReport(scoped.value,applied.value||{}));
const appointments=computed(()=>all.value.filter(r=>inScope(r)&&r.custom_appointment_date_and_time&&String(r.custom_appointment_date_and_time).slice(0,10)>=applied.value?.from_date&&String(r.custom_appointment_date_and_time).slice(0,10)<=applied.value?.to_date));
const matrixRows=computed(()=>branches.value.map(b=>({branch:b.key,...Object.fromEntries(owners.value.map(owner=>{const count=reportGroups(appointments.value.filter(r=>branchOf(r)===b.key&&r.lead_owner===owner),'agent')[0];return [owner,count?count.booked+' / '+count.visits:'0 / 0'];}))})));
const groups=computed(()=>reportGroups(appointments.value,'agent'));
const branches=computed(()=>reportGroups(appointments.value,'branch'));
const metrics=computed(()=>{const total=reportGroups(appointments.value.map(r=>({...r,branch:'All'})))[0]||{};return [['raw','Raw Leads',funnel.value.totals.raw],['quality','Quality Leads',funnel.value.totals.quality],['junk','Junk Leads',funnel.value.totals.junk],['connected','Connected',funnel.value.totals.connected],['appointments','Appointments Due',appointments.value.length],['visits','Walk-ins (Visited)',total.visits||0],['booked','Booked',total.booked||0],['notBooked','Visited – Not Booked',total.notBooked||0],['pending','Outcome Pending',appointments.value.filter(r=>visitStatus(r)==='Visited').length],['noShow','Not Visited',total.noShow||0],['awaiting','Scheduled / Awaiting',total.awaiting||0],['cancelled','Cancelled / Other',total.cancelled||0]];});
const columns=[{key:'key',label:'Agent'},...['appointments','visits','booked','notBooked','noShow','awaiting','showup','conversion'].map(key=>({key,label:({appointments:'Appts Due',visits:'Walk-ins',booked:'Booked',notBooked:'Not Booked',noShow:'Not Visited',awaiting:'Awaiting',showup:'Show-up %',conversion:'Booking %'})[key]}))];
const leadColumns=[{key:'custom_appointment_date_and_time',label:'Appt Date / Time'},{key:'name',label:'Lead ID'},{key:'lead_name',label:'Client'},{key:'mobile_no',label:'Mobile',value:r=>maskPhone(r.mobile_no)},{key:'branch',label:'Branch',value:branchOf},{key:'lead_owner',label:'Agent'},{key:'status',label:'Outcome',value:visitStatus}];
const invoiceColumns=[{key:'invoice_date',label:'Invoice Date'},{key:'invoice',label:'Invoice'},{key:'branch',label:'Branch'},{key:'lead_name',label:'Client'},{key:'lead_owner',label:'Agent'},{key:'source',label:'Source'},{key:'enquired_for',label:'Enquired For'},{key:'with_gst',label:'With GST'},{key:'without_gst',label:'Without GST'},{key:'paid',label:'Paid'},{key:'balance',label:'Balance'}];
const invoices=computed(()=>(financial.value?.cc_invoice_report_summary?.rows||[]).filter(r=>inScope(r)&&(!invoiceQuery.value||Object.values(r).some(v=>String(v).toLowerCase().includes(invoiceQuery.value.toLowerCase())))));
const register=computed(()=>appointments.value.filter(r=>(!outcome.value||visitStatus(r)===outcome.value)&&(!query.value||[r.name,r.lead_name,branchOf(r),r.lead_owner].some(v=>String(v||'').toLowerCase().includes(query.value.toLowerCase())))));
const trends=computed(()=>[...new Set(appointments.value.map(r=>String(r.custom_appointment_date_and_time).slice(0,10)))].sort().map(day=>({key:day,...reportGroups(appointments.value.filter(r=>String(r.custom_appointment_date_and_time).startsWith(day)).map(r=>({...r,branch:day})))[0]})));
watch([scopeMode,selected,selectedAgents,query,outcome],()=>{page.value=1;},{deep:true});
watch(invoiceQuery,()=>{invoicePage.value=1;});
function show(key,title){detailTitle.value=title;const statusMap={visits:r=>visitStatus(r).startsWith('Visited'),booked:r=>visitStatus(r)==='Visited-BKD',notBooked:r=>visitStatus(r)==='Visited-Not BKD',noShow:r=>visitStatus(r)==='Not Visited',awaiting:r=>visitStatus(r)==='Appt Fixed',pending:r=>visitStatus(r)==='Visited',cancelled:r=>/cancel/i.test(visitStatus(r))};detail.value=statusMap[key]?appointments.value.filter(statusMap[key]):key==='appointments'?appointments.value:funnel.value[key]||funnel.value.received;}
</script>
<template><section class="arx-root"><header class="arx-head arx-hero"><div><h2>🎧 Agent Performance Reports</h2><p>Lead received date · appointment date · CC invoices paid in period</p></div><button @click="printReport">🖨 Print / PDF</button></header><div class="arx-filters"><button v-for="[key,label] in [['all','All Agents'],['single','Single Agent'],['multi','Multiple Agents']]" :key="key" :aria-pressed="scopeMode===key" @click="scopeMode=key">{{label}}</button><label v-if="scopeMode==='single'">Agent<select v-model="selected"><option value="">All permitted agents</option><option v-for="owner in owners" :key="owner" :value="owner">{{financial?.agent_names?.[owner]||owner}}</option></select></label><CCChipPicker v-if="scopeMode==='multi'" v-model="selectedAgents" :options="owners.map(value=>({value,label:financial?.agent_names?.[value]||value}))" label="Agents"/></div>
<p v-if="financialLoading" role="status">Loading Agent data…</p><p v-if="financialError" role="alert">{{financialError}} <button @click="loadFinancial">Retry</button></p>
<details open class="arx-sec"><summary class="arx-sh">📊 Performance Snapshot</summary><div class="arx-cards"><button v-for="[key,title,count] in metrics" :key="key" class="arx-card" @click="show(key,title)"><b>{{count}}</b><span>{{title}}</span></button></div><div class="arx-cards"><article v-for="[key,title] in [['with_gst','Invoice value · With GST'],['without_gst','Invoice value · Without GST'],['paid','Paid'],['balance','Balance']]" :key="key" class="arx-card"><b>₹{{invoices.reduce((n,r)=>n+Number(r[key]||0),0).toLocaleString('en-IN')}}</b><span>{{title}}</span></article></div></details>
<CCAgentScorecard v-if="scopeMode==='single'&&selected&&financial&&applied" :data="financial" :range="applied" :owner="selected"/><details open class="arx-sec"><summary class="arx-sh">🏆 Agent Performance</summary><CCDataTable :columns="columns" :rows="groups"/><button @click="downloadCsv('agent-performance.csv',columns,groups)">Export CSV</button></details>
<CCReportKpiRanking v-if="applied" :appointments="financial?.ranking_rows||appointments" :received="marketingReport(financial,applied).received" :names="financial?.agent_names||{}" :from="applied.from_date" :to="applied.to_date" :restricted-owner="financial?.restricted_to_owner?financial.user:''"/><details open class="arx-sec"><summary class="arx-sh">🔻 Conversion Funnel</summary><div class="arx-fun"><div class="arx-fbox"><h3>Lead Funnel · received date</h3><div v-for="key in ['raw','quality','connected','appointments']" :key="key" class="arx-fr"><span>{{key}}</span><meter :value="funnel.totals[key]" :max="Math.max(1,funnel.totals.raw)"/><b>{{funnel.totals[key]}}</b></div></div><div class="arx-fbox"><h3>Appointment Funnel · appointment date</h3><div v-for="[key,title,count] in metrics.filter(x=>['appointments','visits','booked'].includes(x[0]))" :key="key" class="arx-fr"><span>{{title}}</span><meter :value="count" :max="Math.max(1,appointments.length)"/><b>{{count}}</b></div></div></div></details>
<details open class="arx-sec"><summary class="arx-sh">🏥 Branch-wise Report</summary><div class="arx-filters"><button @click="matrix=false">Branch summary</button><button @click="matrix=true">Agent × Branch matrix</button></div><CCDataTable v-if="matrix" :columns="[{key:'branch',label:'Branch'},...owners.map(key=>({key,label:financial?.agent_names?.[key]||key}))]" :rows="matrixRows"/><CCDataTable v-else :columns="[{key:'key',label:'Branch'},...columns.slice(1)]" :rows="branches"/></details>
<details open class="arx-sec"><summary class="arx-sh">📈 Daily Trend</summary><CCReportTrendChart :rows="trends"/><CCDataTable :columns="[{key:'key',label:'Date'},...columns.slice(1)]" :rows="trends"/></details>
<details open class="arx-sec"><summary class="arx-sh">🧭 Lead Source &amp; Treatment Mix</summary><div class="arx-filters"><button @click="mix='source'">Source</button><button @click="mix='category'">Enquired For</button></div><CCDataTable :columns="[{key:'name',label:'Lead Source'},{key:'raw',label:'Raw'},{key:'quality',label:'Quality'},{key:'junk',label:'Junk'},{key:'appointments',label:'Appts Fixed'},{key:'visits',label:'Walk-ins'},{key:'booked',label:'Booked'},{key:'conversion',label:'Booking %'}]" :rows="mix==='source'?funnel.agency:funnel.category"/></details>
<details open class="arx-sec"><summary class="arx-sh">🧾 Revenue Register</summary><input v-model="invoiceQuery" placeholder="Search invoice, client, branch, source…"><CCDataTable :columns="invoiceColumns" :rows="invoices.slice((invoicePage-1)*40,invoicePage*40)"/><CCPager :page="invoicePage" :pages="Math.max(1,Math.ceil(invoices.length/40))" @change="invoicePage=$event"/><button @click="downloadCsv('agent-invoices.csv',invoiceColumns,invoices)">Export CSV</button></details>
<CCAgentPeriodComparison v-if="applied" :anchor="applied.to_date" :owners="scopeMode==='all'?null:scopeMode==='single'?[selected]:selectedAgents"/><details open class="arx-sec"><summary class="arx-sh">📋 Appointment Register</summary><div class="arx-filters"><input v-model="query" placeholder="Search client, lead, branch or agent"><select v-model="outcome"><option value="">All outcomes</option><option v-for="value in [...new Set(appointments.map(visitStatus))]" :key="value">{{value}}</option></select></div><CCDataTable :columns="leadColumns" :rows="register.slice((page-1)*40,page*40)"><template #actions="{row}"><button @click="openLead(row.name)">Open lead</button></template></CCDataTable><CCPager :page="page" :pages="Math.max(1,Math.ceil(register.length/40))" @change="page=$event"/><button @click="downloadCsv('agent-appointments.csv',leadColumns,register)">Export CSV</button></details>
<dialog :open="detail!==null" class="cc-report-dialog cc-agent-detail"><header><h2>{{detailTitle}}</h2><button @click="detail=null">Close</button></header><CCDataTable :columns="leadColumns" :rows="detail||[]"><template #actions="{row}"><button @click="openLead(row.name)">Open lead</button></template></CCDataTable></dialog>
</section></template>
<style scoped src="../../../styles/cc-agent-report.css"></style>
<style scoped>.arx-root{color:#16402d}.arx-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.arx-head h2{margin:0}.arx-sec{margin:12px 0;background:#fffdf7;border:1px solid #d5b66b;border-radius:10px;overflow:hidden}.arx-sec>summary{padding:12px 16px;background:#f2f5ee;font-weight:700;cursor:pointer}.arx-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:9px;padding:12px}.arx-card{display:grid;gap:6px;padding:14px;border:1px solid #d8e4da;border-top:3px solid #26734d;border-radius:8px;background:white;color:inherit;text-align:left;font:inherit}.arx-card strong{font-size:23px}.arx-card span{font-size:12px}.arx-filters{display:flex;gap:12px;flex-wrap:wrap;margin:10px 0}.arx-filters label{display:grid;gap:6px}.arx-fun{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;padding:12px}.arx-fr{display:grid;grid-template-columns:1fr 1fr 40px;gap:8px;margin:10px 0;align-items:center}.arx-fr meter{width:100%}.cc-agent-detail{position:fixed;inset:10vh auto auto 50%;transform:translateX(-50%);z-index:1000;box-shadow:0 0 0 100vmax #102c2266}</style>
